#include <cmath>

using namespace std;

class Solution {
public:
    int findNthDigit(int n) {
        long len = 1, base = 1, digits = 9;
        while (n > digits * len) {
            n -= digits * len;
            len++;
            base *= 10;
            digits *= 10;
        }
        base += (n - 1) / len;
        string s = to_string(base);
        return s[(n - 1) % len] - '0';
    }
};
